	public MarkoutWriterOptions Options => _options;

	protected MarkoutSerializerContext()
		: this(new MarkoutWriterOptions())
	{
	}

	protected MarkoutSerializerContext(MarkoutWriterOptions options)
	{
		ArgumentNullException.ThrowIfNull(options, "options");
		if (options.IsReadOnly)
		{
			throw new InvalidOperationException("Cannot bind a read-only MarkoutWriterOptions instance to a context. The options instance is made read-only when bound to a context.");
		}
		options.MakeReadOnly();
		_options = options;
	}

	public abstract MarkoutTypeInfo<T>? GetTypeInfo<T>();

	public abstract MarkoutSchemaInfo? GetSchemaInfo<T>();

	public abstract IEnumerable<IMarkoutTypeInfo> GetRegisteredTypes();

	[DoesNotReturn]
	private static void ThrowTypeNotRegistered<T>()
	{
		throw new InvalidOperationException($"Type '{typeof(T).FullName}' is not registered in this serializer context. Add [MarkoutContext(typeof({typeof(T).Name}))] to your context class.");
	}

	public string Serialize<T>(T value)
	{
		return Serialize(value, Options);
	}

	public string Serialize<T>(T value, MarkoutWriterOptions options)
	{
		MarkoutTypeInfo<T>? typeInfo = GetTypeInfo<T>();
		if (typeInfo == null)
		{
			ThrowTypeNotRegistered<T>();
		}
