// Single dispatch point: picks the formatter + writer options for the requested format
// and renders the SAME SearchReport model through Markout's serializer.
static string Render(SearchReport report, string format)
{
    var options = new MarkoutWriterOptions();
    Markout.Formatting.IMarkoutFormatter formatter = format switch
    {
        "md" => new MarkdownFormatter(),
        "tsv" => new TableFormatter(),
        "jsonl" => new TableFormatter(),
        _ => throw new ArgumentOutOfRangeException(nameof(format), format, "Unknown format"),
    };

    switch (format)
    {
        case "md":
            options.MaxItems = 3;
            break;
        case "tsv":
            options.TableMode = MarkoutTableMode.Tsv;
            break;
        case "jsonl":
            options.TableMode = MarkoutTableMode.Jsonl;
            break;
    }

    using var writer = new StringWriter();
    MarkoutSerializer.Serialize(report, writer, formatter, ReportContext.Default, options);
    return writer.ToString().TrimEnd('\n', '\r');
}

